            <dd>{L.keyNext ?? 'Next section'}</dd>
            <dt className="flex gap-1">
              <Kbd aria-label="Left arrow">←</Kbd>
              <Kbd>P</Kbd>
            </dt>
            <dd>{L.keyPrevious ?? 'Previous section'}</dd>
            <dt>
              <Kbd>+</Kbd>
